Status Insert(SqList *L, int i, ElemType value) {
    if (i < 0 || i > L->length || L->length == L->capacity) return ERROR;
    for (int j = L->length; j > i; --j) L->data[j] = L->data[j - 1];
    L->data[i] = value;
    ++L->length;
    return OK;
}

snippets.linked-list-update:
Status InsertAfter(Node *p, ElemType value) {
    Node *s = AllocateNode(value);
    if (s == NULL) return ERROR;
    s->next = p->next;
    p->next = s;
    return OK;
}

snippets.stack-implementations:
Status Push(Stack *S, ElemType value) {
    if (S->top == S->capacity) return OVERFLOW;
    S->data[S->top++] = value;
    return OK;
}
Status Pop(Stack *S, ElemType *value) {
    if (S->top == 0) return ERROR;
    *value = S->data[--S->top];
    return OK;
}

snippets.circular-queue:
Status Enqueue(Queue *Q, ElemType value) {
    if ((Q->rear + 1) % Q->capacity == Q->front) return OVERFLOW;
    Q->data[Q->rear] = value;
    Q->rear = (Q->rear + 1) % Q->capacity;
    return OK;
}

snippets.bf-matching:
int BruteForceMatch(String text, String pattern) {
    for (int start = 0; start + pattern.length <= text.length; ++start) {
        int j = 0;
        while (j < pattern.length && text[start + j] == pattern[j]) ++j;
        if (j == pattern.length) return start;
    }
    return NOT_FOUND;
}

snippets.kmp-matching:
int KmpMatch(String text, String pattern, int next[]) {
    int i = 0, j = 0;
    while (i < text.length && j < pattern.length) {
        if (j < 0 || text[i] == pattern[j]) { ++i; ++j; }
        else j = next[j];
    }
    return j == pattern.length ? i - j : NOT_FOUND;
}

