snippets.depth-first-search:
void DFS(Graph G, int u) {
    visited[u] = true;
    Visit(u);
    for (Edge *e = G.first[u]; e != NULL; e = e->next)
        if (!visited[e->to]) DFS(G, e->to);
}

snippets.breadth-first-search:
void BFS(Graph G, int start) {
    Queue Q; Init(&Q);
    visited[start] = true; Enqueue(&Q, start);
    while (!Empty(Q)) {
        int u = Dequeue(&Q); Visit(u);
        for each (int v in Adjacent(G, u))
            if (!visited[v]) { visited[v] = true; Enqueue(&Q, v); }
    }
}

