snippets.binary-search:
int BinarySearch(Elem a[], int n, Key key) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (a[mid].key == key) return mid;
        if (a[mid].key < key) low = mid + 1; else high = mid - 1;
    }
    return NOT_FOUND;
}

