snippets.hash-tables:
int FindSlot(Table T, Key key) {
    int start = Hash(key) % T.capacity;
    for (int step = 0; step < T.capacity; ++step) {
        int i = (start + step) % T.capacity;
        if (T[i].empty || T[i].key == key) return i;
    }
    return TABLE_FULL;
}

